B.NM=s(["CHAPTER 1",""," \uc774 \uc138\uc0c1\uc5d0\ub294 \ub450\uac1c\uc758 \uac1c\ub150\uc774 \ud544\uc694\ud558\ub2e4."," \uadf8\uac83\uc740 \ubc14\ub85c \uc120\uacfc \uc545\uc774\ub2e4."," \uc804\uc790\uc758 \uc0c1\uc9d5\uc740 Lord Ahn \uc774\uace0, \ud6c4\uc790\uc758 \uc0c1\uc9d5\uc740","Ancient Evil \uc774\ub2e4."],t.s)
B.Oq=s(["CHAPTER 2",""," \ub9cc\uc57d \ub2f9\uc2e0\uc774 \ud669\uc57c\uc5d0\uc11c Ancient Evil\uc744 \ub9cc\ub098\ub354","\ub77c\ub3c4 \ub450\ub824\uc6cc\ud558\uc9c0 \ub9d0\ub77c. \uadf8\ub294 \ube44\ub85d \uc545\uc758 \ud45c\uc0c1\uc774","\uc9c0\ub9cc Necromancer \uac00 \ud589\ud558\ub294 \uc545\uacfc\ub294 \ub2e4\ub978 \ud45c\ud604",'\uc784\uc744 \uba85\uc2ec\ud558\ub77c. \ub9cc\uc57d \uc138\uc0c1\uc774 "\uc120"\ub9cc\uc774 \uc788\uace0 \uc774','\ub7f0 "\uc545"\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74  \ub204\uad6c\ub3c4 \uc120\uc758 \uc911',"\uc694\uc131\uc744 \uc778\uc2dd\ud558\uc9c0 \ubabb\ud55c\ucc44 \ubcf4\ud3b8\uc801\uc778 \uc9c4\ub9ac\ub85c\ub9cc \uc778","\uc2dd\ub418\uc5b4\uac00\ub294 \uc2dc\ub300\uac00 \uc62c\uac83\uc774\uba70 \uc120\uc73c\ub85c \ub458\ub7ec \uc313\uc5ec","\uc9c4 \uc0dd\ud65c\uc5d0 \ub300\ud55c \uace0\ub9c8\uc6c0\uc744 \ub9dd\uac01\ud558\ub294 \uc2dc\ub300\uac00  \uc6b0","\ub9ac \uc55e\uc5d0 \ub3c4\ub798\ud558\ub294 \ub54c\uac00 \uacb0\uad6d \uc62c\uac83\uc774\ub2e4. \uadf8\ub7f0\ub54c","\uac00 \uc624\uae30\uc804\uc5d0 \uc0ac\ub78c\ub4e4\uc774  \uc774\ub7f0 \uc120\uc758 \uc18c\uc911\ud568\uc744 \ub290","\ub07c\uace0 \uc2a4\uc2a4\ub85c \uc9c0\ud0a4\ub824\uace0 \ub178\ub825\ud558\uac8c  \ub9cc\ub4e4  \ud558\ub098\uc758","\uac1c\ub150\uc774 \ud544\uc694\ud558\uac8c \ub418\uc5c8\ub294\ub370 \uc774\uac83\uc774 \ubc14\ub85c \ud0dc\ucd08\uc5d0","\uc0dd\uaca8\ub09c \uc545\uc758 \uac1c\ub150\uc774\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \uc77c\ubd80\ub7ec \ubb47 \uc0ac","\ub78c\ub4e4\uc5d0\uac8c \ube44\ub09c\uc744 \uc0ac\uba74\uc11c \uae4c\uc9c0 \uc545\uc744 \ub300\ud45c\ud574\uc904\ub9cc","\ud55c \uc790\ub294 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc558\ub2e4. \uc774\uc5d0 \uc2a4\uc2a4\ub85c\ub97c \uc545\uc758","\uc9d1\ub300\uc131\uc73c\ub85c \ubd88\ub7ec\uc8fc\uae30\ub97c \uc694\uad6c\ud558\ub294 \ud55c \ud604\uc790\uac00 \uc788","\uc5c8\uc73c\ub2c8 \ubcf8\uba85\uc740 \uc54c\uc218 \uc5c6\uc9c0\ub9cc \uadf8\uac00 \ubc14\ub85c Ancient","Evil\uc774\ub77c\uace0 \uce6d\ud558\ub294 \uc790\uc600\ub2e4.  \uc120\uc5d0 \uc758\ud574 \ubcf4\ud638\ub418","\uc5b4 \ub108\ubb34\ub098\ub3c4 \ud3c9\ud654\ub85c\uc6b4 \uc0dd\ud65c\uc744 \ud574\uc654\ub358 \uc0ac\ub78c\ub4e4\uc740","\uc774\uc81c \uc0c8\ub85c\uc6b4 \ub9c8\uc74c\uc744 \uac16\uace0 \uadf8\uc5d0\uac8c \ub300\ud56d\ud558\ub294  \uc790","\uc138\ub97c \ucde8\ud558\uac8c \ub418\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub294 \uc2e4\uc9c0\ub85c \uc0ac\ub78c","\ub4e4\uc5d0\uac8c \ud574\ub97c \uc785\ud788\uc9c0 \uc54a\uc558\uc73c\uba70  \uadf8\uc758 \ubcf8\uc2ec\uc740 \uc120","\uc5d0 \uc788\ub2e4\ub294\uac78 \uc54c\uc544\ub450\uae30 \ubc14\ub780\ub2e4."],t.s)
